+        tilt: None,
+        stock_to_leave: 0.0,
+        clearance_z: Height::fixed(20.0),
+        retract_z: Height::fixed(15.0),
+        top_z: Height::fixed(10.0),
+        bottom_z: Height::fixed(4.0),
+        stepdown: 2.0,
+        feed: 800.0,
+        plunge_feed: 200.0,
+        climb: true,
+        side: Side::Auto,
+        lead: Lead::None,
+        tolerance: 0.01,
+        tab_count: 0,
+        tab_width: 0.0,
+        tab_height: 0.0,
+        entry: camcraft_app::machining3d::Entry3D::Plunge,
